// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Campfire".
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2764853/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
  createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
  resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1., h=.0;
	for (float i=.0; i++<5.;) {
		t+=a*noise(p-T);
		a*=.5;
		h+=a;
		p*=1.75;
	}
	return t/h;
}
vec3 map(vec3 p) {
	p.xz*=rot(.42);
	const float k=.25;
	p.x=mod(p.x,1.)-.5;
	float idx=floor(p.x+.5);
	p.z-=clamp(round(p.z*k),.0,2.)/k;
	float idy=round(p.z);
	return vec3(length(p.xz)-.2,idx,idy);
}
float march(inout vec3 p, vec3 rd, out vec2 id) {
	float dd=.0;
	for (int i; i++<120;) {
		vec3 d=map(p);
		if (abs(d.x)<1e-3) {
			id=d.yz;
			break;
		}
		if (dd>10.) break;
		p+=rd*d.x;
		dd+=d.x;
	}
	return dd;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).x+
		k.yxy*map(p+k.yxy*h).x+
		k.yyx*map(p+k.yyx*h).x+
		k.xxx*map(p+k.xxx*h).x
	);
}
float shadow(vec3 p, vec3 rd) {
	float shd=1., maxd=distance(p,rd);
	vec3 l=N(rd-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i).x;
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,16.*d/i);
		i+=d;
	}
	return shd;
}
void cam(inout vec3 p) {
	p.yz*=rot(sin(T+.2*noise(p.yz*4.))*.01);
	p.xz*=rot(cos(T+.2*noise(p.xz*12.))*.01);
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-3),
	rd=N(vec3(uv,1.-.3*dot(uv,uv)));
	cam(p); cam(rd);
	float d=mix(fbm(vec2(T,uv.x)),fbm(uv),.5);
	vec2 id;
	if (march(p,rd,id)<10.) {
		vec3 n=norm(p), lp=vec3(d,d,-10), l=N(lp-p);
		float dif=clamp(dot(l,n),.0,1.), shd=shadow(p+n*5e-2,lp);
		col+=dif*.12*hue(.4*noise(vec2(p.y*id.x,p.y)*80.+id*80.+noise(p.xy*40.)));
		col*=shd;
		col=mix(col,vec3(2),dot(col,vec3(.21,.71,.07)));
		col=mix(col,col*.5,d*d);
		vec2 v=2.*(FC/R)-1.;
		v*=1.3;
		col=mix(col,vec3(0),clamp(dot(v*v,v*v),.0,1.));
	}
	uv.x+=sin(T*2.+4.*uv.y)*.02;
	uv.x*=5.;
	uv.y-=T;

	// could be as simple as
	//float d=fbm(uv);
	// or as sophisticated as
	d=mix(fbm(vec2(T,uv.x)),fbm(uv),.5);
	col+=mix(mix(vec3(1,.7,.2),vec3(1,0,0),S(.5,1.,d+max(.1,uv.y*2.+1.))),vec3(0),S(.8,1.5,d+.5+FC.y/R.y));
	O=vec4(col,1);
}

